"""Stable errors. Messages generated by the SDK never contain server response text."""


class ThunderIDError(Exception):
    origin = "thunderid"

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


class ThunderIDRuntimeError(ThunderIDError):
    pass


class ThunderIDAPIError(ThunderIDError):
    def __init__(self, code: str, message: str, status_code: int, status_text: str) -> None:
        self.status_code = status_code
        self.status_text = status_text
        super().__init__(code, message)
